changeSet.sql:
CREATE TEMPORARY TABLE nine_part_organisation ON COMMIT DROP AS
  SELECT DISTINCT organisation_address.organisation_id
  FROM organisation_address
  JOIN address ON address.id = organisation_address.address_id
  WHERE address.address_line_1 IS NULL;
DELETE FROM organisation_address WHERE organisation_id IN (SELECT organisation_id FROM nine_part_organisation);
DELETE FROM organisation WHERE id IN (SELECT organisation_id FROM nine_part_organisation);
DELETE FROM address WHERE address_line_1 IS NULL;
